import { Fragment, useEffect } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import { useSkin } from "@hooks/useSkin";
import { ChevronDown } from "react-feather";
import { columns } from "./datatable/columns";
import DataTable from "react-data-table-component";
import {
  UncontrolledAccordion,
  AccordionItem,
  AccordionHeader,
  AccordionBody,
  Card,
  Row,
  Col,
  Label,
  Input,
  Button,
} from "reactstrap";
import Select from "react-select";
import { selectThemeColors } from "@utils";
import { useSelector, useDispatch } from "react-redux";
import Confirm from "../../../components/confirm";
import { setDeleteModal } from "../../../redux/rates_slice";
import useRate from "../../../hooks/use_rate";
import ReactPaginate from "react-paginate";
import ProgressLoading from "../../../components/progress_loading";

const AllRates = () => {
  const { skin } = useSkin();
  const dispatch = useDispatch();
  const {
    getRates,
    deleteRate,
    rateList,
    filters,
    setFilters,
    ratePaginates,
    setRatePaginates,
    rateLoadings,
  } = useRate();

  const deleteModal = useSelector((state) => state.rates.deleteModal);
  const selectedRate = useSelector((state) => state.rates.selectedRate);

  const handlePagination = (page) => {
    setRatePaginates({ ...ratePaginates, current: page.selected });
    getRates(page.selected + 1, filters);
  };

  // ** Custom Pagination
  const CustomPagination = () => (
    <ReactPaginate
      previousLabel=""
      nextLabel=""
      forcePage={ratePaginates.current - 1}
      onPageChange={(page) => handlePagination(page)}
      pageCount={ratePaginates.total}
      breakLabel="..."
      pageRangeDisplayed={2}
      marginPagesDisplayed={2}
      activeClassName="active"
      pageClassName="page-item"
      breakClassName="page-item"
      nextLinkClassName="page-link"
      pageLinkClassName="page-link"
      breakLinkClassName="page-link"
      previousLinkClassName="page-link"
      nextClassName="page-item next-item"
      previousClassName="page-item prev-item"
      containerClassName="pagination react-paginate separated-pagination pagination-sm justify-content-end pe-1 mt-1"
    />
  );

  useEffect(() => {
    setRatePaginates({ ...ratePaginates, current: 1 });
    getRates(1, filters);
  }, []);

  return (
    <Fragment>
      <Breadcrumbs
        title="Rates List"
        data={[{ title: "Rates" }, { title: "Rates List" }]}
      />
      {/* filterbar */}
      <Card>
        <UncontrolledAccordion>
          <AccordionItem>
            <AccordionHeader targetId="1">Filters</AccordionHeader>
            <AccordionBody accordionId="1">
              <Row>
                {/* category */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="category">category</Label>
                  <Select
                    isClearable={false}
                    theme={selectThemeColors}
                    closeMenuOnSelect={true}
                    placeholder="select option"
                    maxMenuHeight={120}
                    options={[
                      { label: "video", value: "video" },
                      { label: "voice", value: "voice" },
                      { label: "data", value: "data" },
                      { label: "monetary", value: "monetary" },
                    ]}
                    className={`react-select`}
                    classNamePrefix="select"
                    id="category"
                    name="category"
                    value={filters.category}
                    onChange={(value) => {
                      setFilters({ ...filters, category: value });
                    }}
                  />
                </Col>
                {/* source_mcc */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="source_mcc">source_mcc</Label>
                  <Input
                    value={filters.source_mcc}
                    onChange={(e) => {
                      setFilters({ ...filters, source_mcc: e.target.value });
                    }}
                    name="source_mcc"
                    id="source_mcc"
                  />
                </Col>
                {/* source_mnc */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="source_mnc">source_mnc</Label>
                  <Input
                    value={filters.source_mnc}
                    onChange={(e) => {
                      setFilters({ ...filters, source_mnc: e.target.value });
                    }}
                    name="source_mnc"
                    id="source_mnc"
                  />
                </Col>
                {/* destination_mcc */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="destination_mcc">destination_mcc</Label>
                  <Input
                    value={filters.destination_mcc}
                    onChange={(e) => {
                      setFilters({
                        ...filters,
                        destination_mcc: e.target.value,
                      });
                    }}
                    name="destination_mcc"
                    id="destination_mcc"
                  />
                </Col>
                {/* destination_mnc */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="destination_mnc">destination_mnc</Label>
                  <Input
                    value={filters.destination_mnc}
                    onChange={(e) => {
                      setFilters({
                        ...filters,
                        destination_mnc: e.target.value,
                      });
                    }}
                    name="destination_mnc"
                    id="destination_mnc"
                  />
                </Col>
                {/* actions */}
                <Col xs="12" className={"d-flex justify-content-end"}>
                  <Button
                    style={{ marginRight: 8 }}
                    color="danger"
                    onClick={() => {
                      setRatePaginates({ ...ratePaginates, current: 1 });
                      getRates(1, {
                        category: null,
                        source_mcc: "",
                        source_mnc: "",
                        destination_mcc: "",
                        destination_mnc: "",
                      });
                      setFilters({
                        category: null,
                        source_mcc: "",
                        source_mnc: "",
                        destination_mcc: "",
                        destination_mnc: "",
                      });
                    }}
                  >
                    Clear
                  </Button>
                  <Button
                    onClick={() => {
                      setRatePaginates({ ...ratePaginates, current: 1 });
                      getRates(1, filters);
                    }}
                    style={{ width: 150 }}
                    color="primary"
                  >
                    Filter
                  </Button>
                </Col>
              </Row>
            </AccordionBody>
          </AccordionItem>
        </UncontrolledAccordion>
      </Card>
      {/* datatable */}
      <div className="react-dataTable mv_datatable_container">
        <DataTable
          noDataComponent={
            rateLoadings.getRates ? (
              ""
            ) : (
              <div style={{ margin: "24px 0" }}>No Rate Founded!</div>
            )
          }
          noHeader
          pagination
          columns={columns}
          paginationPerPage={ratePaginates.per_page}
          className="react-dataTable"
          sortIcon={<ChevronDown size={10} />}
          paginationComponent={CustomPagination}
          data={rateList}
          theme={skin === "dark" ? "darkTheme" : ""}
        />
        {rateLoadings.getRates ? (
          <div className="datatable_loading_cover">
            <ProgressLoading />
          </div>
        ) : null}
      </div>
      {/* delete modal */}
      <Confirm
        visible={deleteModal}
        setVisible={setDeleteModal}
        title={"Are you sure you want to delete this rate?"}
        noAction={() => dispatch(setDeleteModal(null))}
        noColor={"secondary"}
        noTitle={"Cancel"}
        yesLoading={rateLoadings.deleteRate}
        yesAction={() => {
          deleteRate(selectedRate.ID, filters);
        }}
        yesColor={"danger"}
        yesTitle={"Delete"}
        type={"global"}
        size={"md"}
      />
    </Fragment>
  );
};
export default AllRates;
