import { useState } from "react";
import useHttp from "./use_http";
import { useFormik } from "formik";
import { createRateSchema, updateRateSchema } from "../utility/schemas";
import toast from "react-hot-toast";
import { useNavigate } from "react-router-dom";
import { useDispatch } from "react-redux";
import { setDeleteModal, setSelectedRate } from "../redux/rates_slice";

const useRate = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { httpService } = useHttp();

  const [rateLoadings, setRateLoadings] = useState({
    getRates: false,
    createRate: false,
    updateRate: false,
    deleteRate: false,
    getRateById: false,
  });
  const [ratePaginates, setRatePaginates] = useState({
    current: 1,
    total: 1,
    per_page: 10,
  });

  const [filters, setFilters] = useState({
    category: null,
    source_mcc: "",
    source_mnc: "",
    destination_mcc: "",
    destination_mnc: "",
  });

  const [rateList, setRateList] = useState([]);

  const getRates = async (page, filtersData) => {
    const paramsData = {
      page: page,
    };
    if (filtersData.category) {
      paramsData["category"] = filtersData?.category?.value;
    }
    if (filtersData.source_mcc.length > 0) {
      paramsData["source_mcc"] = filtersData?.source_mcc;
    }
    if (filtersData.source_mnc.length > 0) {
      paramsData["source_mnc"] = filtersData?.source_mnc;
    }
    if (filtersData.destination_mcc.length > 0) {
      paramsData["destination_mcc"] = filtersData?.destination_mcc;
    }
    if (filtersData.destination_mnc.length > 0) {
      paramsData["destination_mnc"] = filtersData?.destination_mnc;
    }
    try {
      setRateLoadings({ ...rateLoadings, getRates: true });
      const response = await httpService.get(`/v1/rates`, {
        params: paramsData,
      });
      setRateLoadings({ ...rateLoadings, getRates: false });
      setRatePaginates({
        ...ratePaginates,
        current: response.data.meta.page,
        total: response.data.meta.pages,
        per_page: response.data.meta.limit,
      });
      if (response.data.data) {
        setRateList(response.data.data);
      } else {
        setRateList([]);
      }
    } catch ({ err, response }) {
      setRateLoadings({ ...rateLoadings, getRates: false });
    }
  };

  const createRateController = useFormik({
    initialValues: {
      Name: "",
      persian_name: "",
      category: null,
      source_mcc: "",
      source_mnc: "",
      destination_mcc: "",
      destination_mnc: "",
      per: "",
      monetary_unit: "",
      non_monetary_unit: "",
      applicable_from: "",
      applicable_till: "",
    },
    validationSchema: createRateSchema,
    onSubmit: (values) => {
      createRate(values);
    },
  });

  const createRate = async (values) => {
    let postData = {
      Name: values.Name,
      persian_name: values.persian_name,
      category: values.category?.value,
      source_mcc: values.source_mcc,
      source_mnc: values.source_mnc,
      destination_mcc: values.destination_mcc,
      destination_mnc: values.destination_mnc,
      per: parseFloat(values.per),
      monetary_unit: parseFloat(values.monetary_unit),
      non_monetary_unit: parseFloat(values.non_monetary_unit),
      applicable_from: values.applicable_from,
      applicable_till: values.applicable_till,
    };
    try {
      setRateLoadings({ ...rateLoadings, createRate: true });
      const response = await httpService.post(`/v1/rates`, postData);
      setRateLoadings({ ...rateLoadings, createRate: false });
      if (response.status == 200 || response.status == 201) {
        toast.success("Rate created successfully");
        navigate("/rates/all");
      } else {
        toast.error(response.data.data);
      }
    } catch ({ err, response }) {
      setRateLoadings({ ...rateLoadings, createRate: false });
    }
  };

  const deleteRate = async (rate_id, filtersData) => {
    try {
      setRateLoadings({ ...rateLoadings, deleteRate: true });
      const response = await httpService.delete(`/v1/rates/${rate_id}`);
      if (response.status === 200 || response.status == 201) {
        setRateLoadings({ ...rateLoadings, deleteRate: false });
        toast.success("Balance deleted successfully.");
        dispatch(setDeleteModal(null));
        dispatch(setSelectedRate(null));
        setRatePaginates({ ...ratePaginates, current: 1 });
        getRates(1, filtersData);
      } else {
        toast.error(response.data.data);
      }
    } catch ({ err, response }) {
      setRateLoadings({ ...rateLoadings, deleteRate: false });
    }
  };

  const updateRateController = useFormik({
    initialValues: {
      rate_id: null,
      monetary_unit: "",
      non_monetary_unit: "",
    },
    validationSchema: updateRateSchema,
    enableReinitialize: true,
    onSubmit: (values) => {
      updateRate(values);
    },
  });

  const updateRate = async (values) => {
    let postData = {
      monetary_unit: parseFloat(values.monetary_unit),
      non_monetary_unit: parseFloat(values.non_monetary_unit),
    };
    try {
      setRateLoadings({ ...rateLoadings, updateRate: true });
      const response = await httpService.patch(
        `/v1/rates/${values.rate_id}`,
        postData
      );
      setRateLoadings({ ...rateLoadings, updateRate: false });
      if (response.status == 200 || response.status == 201) {
        toast.success("Rate updated successfully.");
        navigate("/rates/all");
      } else {
        toast.error(response.data.data);
      }
    } catch ({ err, response }) {
      setRateLoadings({ ...rateLoadings, updateRate: false });
    }
  };

  const getRateById = async (rate_id) => {
    try {
      setRateLoadings({ ...rateLoadings, getRateById: true });
      const response = await httpService.get(`/v1/rates/${rate_id}`);
      setRateLoadings({ ...rateLoadings, getRateById: false });
      if (response.status == 200 || response.status == 201) {
        updateRateController.setFieldValue("rate_id", response.data.data.ID);
        updateRateController.setFieldValue(
          "monetary_unit",
          response.data.data.MonetaryUnit
        );
        updateRateController.setFieldValue(
          "non_monetary_unit",
          response.data.data.NonMonetaryUnit
        );
      } else {
        toast.error(response.data.data);
        navigate("/rates/all");
      }
    } catch ({ err, response }) {
      setRateLoadings({ ...rateLoadings, getRateById: false });
      navigate("/rates/all");
    }
  };

  const exports = {
    getRates,
    getRateById,
    deleteRate,
    rateList,
    filters,
    setFilters,
    createRateController,
    updateRateController,
    ratePaginates,
    setRatePaginates,
    rateLoadings,
  };
  return exports;
};
export default useRate;
